function barRows(rev,total){return Object.entries(rev).sort((a,b)=>b[1]-a[1]).filter(([,v])=>v!==0).map(([k,v])=>{const label=k==='地方交付税'&&!data().official&&city().pref==='東京都'&&/^131\d\d$/.test(city().code)?'地方交付税区分※（特別区交付金）':k;return `<div class="barrow"><div class="barlabel"><span>${esc(label)}</span><span>${oku(v*1000)} · ${(v/total*100).toFixed(1)}%</span></div><div class="bartrack"><div class="barfill" style="width:${Math.max(0,v/total*100)}%"></div></div></div>`}).join('')}
