function projectCard(p){return `<article class="project"><div class="kicker">${tag(p.pref+' '+p.city,'green')}${tag(p.year+'年度交付金資料')}<span>${esc(p.category)}</span></div><h3>${esc(p.name)}</h3><div class="route"><div><small>01 国の制度</small><b>重点支援地方交付金</b><small>RS予算事業ID 7629</small></div><div><small>02 自治体への財源</small><b>${oku(p.grant)}</b><small>当該事業の交付金充当額</small></div><div><small>03 事業の実施</small><b>${oku(p.total)}</b><small>総事業費 · ${esc(p.period)}</small></div><div class="last"><small>04 公表された実績</small><b>${esc(p.output)}</b></div></div><div class="project-foot"><span>資料照合済 · ${esc(p.row)} · 金額は実績報告資料ベース</span><button class="mini-btn" data-detail="${p.id}">実績と成果を確認 →</button></div></article>`}
function traceView(){const list=traces.projects.filter(p=>(state.scope==='all'||p.code===state.city)&&(!state.query||(p.name+p.city+p.category).includes(state.query))&&(!state.category||p.category===state.category));return `<div class="section-top"><h2>財源から、暮らしの変化へ</h2>${tag('実資料を照合した6事業','green')}</div><p class="metricdesc">事業資料は2024年度の交付金に関するものです。上部の財政データ年度とは独立して表示します。掲載事業は全事業の一部です。</p><div class="note blue">国の制度名 → 自治体の交付金充当額 → 総事業費 → 公表実績を接続しています。国のRS予算事業ID 7629と制度名で照合済みです。自治体別交付額の全件突合・税目別財源・間接配分は未接続です。</div><div class="trace-head"><label class="small" for="scope">対象</label><select id="scope"><option value="city" ${state.scope==='city'?'selected':''}>選択中の自治体</option><option value="all" ${state.scope==='all'?'selected':''}>照合済みの全自治体</option></select><input id="projectSearch" aria-label="事業を検索" placeholder="事業名・分野で検索" value="${esc(state.query)}"><select id="category" aria-label="事業分野"><option value="">すべての分野</option>${['暮らし','交通','福祉','産業'].map(k=>`<option ${k===state.category?'selected':''}>${k}</option>`).join('')}</select></div><p class="small" role="status">${list.length}事業を表示 · 「未収録」は成果がないことを意味しません。</p>${list.length?list.map(projectCard).join(''):`<div class="empty"><h3>この条件の事業データは、まだ収録していません。</h3><p class="small">文京区3事業・氷見市3事業を照合済みです。ほかの自治体の事業・成果は未収録です。</p><button class="action" id="showAll">照合済みの全6事業を見る</button></div>`}<div class="note">支給件数・維持した路線数などの「実施量」と、家計の改善などの「成果」を区別します。自治体自身の効果説明は、その記載として表示し、サイトによる効果認定には使いません。</div>`}
function compareView(){const a=city(),b=db.cities.find(c=>c.code===state.compare)||db.cities[0],da=data(a),d=data(b),per=state.unit==='person',value=(n,dd)=>per?fmt(Math.round(n*1000/dd.population))+'円':oku(n*1000);return `<div class="section-top"><h2>同じ物差しで、比べる。</h2>${tag(state.year+'年度')}</div><section class="panel"><div class="compare-controls"><label>比較する自治体<select id="compareCity">${db.cities.map(c=>`<option value="${c.code}" ${c.code===b.code?'selected':''}>${esc(c.pref+' '+c.name)}</option>`).join('')}</select></label><label>金額の見方<select id="unit"><option value="total" ${!per?'selected':''}>実額</option><option value="person" ${per?'selected':''}>人口1人あたり</option></select></label></div><div class="tablewrap"><table><thead><tr><th>指標</th><th class="num">${esc(a.pref+' '+a.name)}</th><th class="num">${esc(b.pref+' '+b.name)}</th></tr></thead><tbody><tr><td>人口</td><td class="num">${fmt(da.population)}人</td><td class="num">${fmt(d.population)}人</td></tr><tr><td>類似団体区分</td><td class="num">${esc(da.group)}</td><td class="num">${esc(d.group)}</td></tr>${['歳入総額',...(da.spending&&d.spending?['歳出総額','民生費','教育費','土木費']:[]),'地方税','国庫支出金','都道府県支出金'].map(k=>`<tr><td>${k}</td><td class="num">${value(compareAmount(da,k),da)}</td><td class="num">${value(compareAmount(d,k),d)}</td></tr>`).join('')}${['財政力指数','経常収支比率','実質公債費比率'].map(k=>`<tr><td>${k}</td><td class="num">${indicator(da,k)}</td><td class="num">${indicator(d,k)}</td></tr>`).join('')}</tbody></table></div><div class="note">人口規模・年齢構成・地理・災害・担う事務が異なります。金額の大小だけで効率や行政の優劣を判定できません。東京23区と一般市の財源制度にも違いがあります。</div><button class="action" id="download">比較データをCSVで保存 ↓</button><p class="small">出典：${link(state.year==='2024'?officialSource:source,state.year==='2024'?'総務省・2024年度原表':'Japan Dashboard／デジタル庁・総務省')}</p></section>`}
function treeAmount(n){if(state.treeUnit==='yen')return fmt(n*1000)+'円';if(state.treeUnit==='person')return fmt(Math.round(n*1000/data().population))+'円';return n>=100000?oku(n*1000):n>=10?fmt(Number((n/10).toFixed(1)))+'万円':fmt(n*1000)+'円'}
function loadTree(){if(spendingTree||treeLoading)return;treeLoading=true;treeError=false;fetch('spending-tree.json').then(r=>{if(!r.ok)throw Error('load failed');return r.json()}).then(v=>{spendingTree=v;treeLoading=false;if(state.tab==='tree')render()}).catch(()=>{treeLoading=false;treeError=true;if(state.tab==='tree')render()})}
function expenditureTree(){
 if(state.treeMode==='ledger')return ledgerView();
 if(state.year!=='2024')return `<div class="section-top"><h2>支出の内訳をたどる</h2>${tag(state.year+'年度')}</div><div class="empty"><h3>ツリーは2024年度に対応しています。</h3><p>原表の階層と総額を確認できた2024年度に切り替えてご覧ください。</p><button class="action" id="treeYear2024">2024年度のツリーを開く</button></div>`;
 if(!spendingTree){if(!treeError)loadTree();return `<section class="panel"><h2>支出の内訳をたどる</h2><p role="status">${treeError?'ツリーデータを読み込めませんでした。':'支出の細目を読み込んでいます…'}</p>${treeError?'<button class="action" id="retryTree">再読み込み</button>':''}</section>`}
 const kind=state.treeMode,cols=spendingTree.columns[kind],values=spendingTree.cities[state.city][kind],raw=Object.fromEntries(cols.map((c,i)=>[c,values[i]])),nodes=spendingTree.schema[kind],total=data().official.spendingTotal,q=state.treeQuery.trim();
 const amount=n=>n.cols.reduce((a,c)=>a+raw[c],0),matches=n=>!q||n.label.includes(q)||n.children.some(matches),zero=n=>state.treeZeros||amount(n)!==0;
 let visible=0;
 const draw=(list,parent,path='',ancestorMatch=false)=>list.filter(n=>zero(n)&&(ancestorMatch||matches(n))).map(n=>{visible++;const value=amount(n),key=state.city+'|'+kind+'|'+path+'/'+n.label,isMatch=q&&n.label.includes(q),hasKids=n.children.length>0,percentage=parent===0?'—':(value/parent*100).toFixed(1)+'%',totalPct=total===0?'—':(value/total*100).toFixed(2)+'%',line=`<span class="tree-name">${isMatch?'<mark>'+esc(n.label)+'</mark>':esc(n.label)}<small>歳出全体の ${totalPct}</small></span><strong class="tree-money">${treeAmount(value)}</strong><span class="tree-share">${percentage}</span>`,attrs=`data-branch="${esc(key)}"`;
 if(!hasKids)return `<div class="tree-leaf tree-line">${line}</div>`;
 return `<details class="tree-node" ${attrs} ${q||openBranches.has(key)?'open':''}><summary class="tree-line">${line}</summary><div class="tree-children">${draw(n.children,value,path+'/'+n.label,ancestorMatch||!!isMatch)}</div></details>`}).join('');
 const content=draw(nodes,total);return `<div class="section-top"><h2>${esc(city().name)}の支出をたどる</h2>${tag('2024年度・全国1,741自治体','green')}</div><p class="metricdesc">項目を押すと下の細目が開きます。親項目に対する割合と、歳出全体に対する割合を確認できます。</p><section class="panel tree-panel"><div class="tree-tools">${ledgerModes()}<label class="small">表示金額<select id="treeUnit"><option value="auto" ${state.treeUnit==='auto'?'selected':''}>億円・万円（自動）</option><option value="yen" ${state.treeUnit==='yen'?'selected':''}>円（正確な金額）</option><option value="person" ${state.treeUnit==='person'?'selected':''}>住民1人あたり</option></select></label></div><div class="tree-tools"><input type="search" id="treeSearch" aria-label="支出ツリーの項目を検索" placeholder="公園費・小学校費・委託料など" value="${esc(q)}"><label class="tree-check"><input type="checkbox" id="treeZeros" ${state.treeZeros?'checked':''}>0円の項目も表示</label><button class="mini-btn" id="expandTree">すべて開く</button><button class="mini-btn" id="collapseTree">すべて閉じる</button></div><p class="small" role="status">${q?esc(q)+'に一致する項目と、その上の階層を表示。':'親項目と内訳は同じ支出です。両方の金額を足しません。'} ${state.treeUnit==='person'?'人口 '+fmt(data().population)+'人で算出。':''}</p><div class="tree-root"><span>歳出総額</span><strong>${treeAmount(total)}</strong><span>100%</span></div><div class="tree-columns"><span>項目 ／ 歳出全体に占める割合</span><span>金額</span><span>親に占める割合</span></div><div id="treeBranches">${content||'<div class="empty">一致する支出項目がありません。</div>'}</div><p class="small">${link(data().official.tables[kind].url,'原表Excelで確認')} · 原表${data().official.tables[kind].row}行 · 金額の原単位は千円（円表示でも千円未満の精度はありません）。</p></section><div class="note blue">全国共通の地方財政統計の細目までを表示しています。「児童福祉費」「委託料」などの下にある個別事業名・契約先・支払先は、別資料で確認しています。文京区2024年度の収録資料を別画面で開けます。目的別と性質別は同じ支出の別分類で、1本の階層には結合しません。</div><button class="action" id="openParties">個別事業・契約先・支払先を見る →</button><details><summary>階層と金額の確認について</summary><p class="small">全1,741自治体で、各階層の子項目合計と親項目金額を照合しました。検査数 ${fmt(spendingTree.validation.parentChildEqualities)}件、差額0件。原表の「うち」内数は加算する子項目から除外しています。原表の「-」は金額集計上0として扱います。項目名の検索は照合済みの統計細目のみが対象です。</p></details>`
}
function compareAmount(d,k){if(k==='歳入総額')return d.official?.revenueTotal??sum(d.revenue);if(k==='歳出総額')return d.official.spendingTotal;if(['民生費','教育費','土木費'].includes(k))return d.spending[k];return d.revenue[k]||0}
function nationalView(){const n=national,b=n.summary.find(r=>r.fiscalYear==='2024');return `<div class="section-top"><h2>国の事業から、地域へ。</h2>${tag('RS予算事業ID '+n.id,'green')}</div><section class="panel"><p class="eyebrow">${esc(n.ministry+' ／ '+n.office)}</p><h3>${esc(n.name)}</h3><p class="small">2025年度レビューシートに掲載された2024年度実績。上部の自治体・財政年度フィルターとは独立して表示します。</p><div class="stats"><div class="stat"><span class="label">2024年度 歳出予算現額</span><strong>${oku(b.budget)}</strong></div><div class="stat primary"><span class="label">2024年度 執行額</span><strong>${oku(b.execution)}</strong></div><div class="stat"><span class="label">翌年度への繰越額</span><strong>${oku(b.carryover)}</strong></div></div><p class="small">原単位：円。予算現額は当初予算とは異なります。予算と執行と繰越を合算しません。</p><div class="route"><div><small>01 所管</small><b>内閣府</b></div><div><small>02 執行経路</small><b>総務省へ予算移替え</b></div><div><small>03 国側の支出ブロックB</small><b>地方公共団体 1,788団体</b></div><div class="last"><small>04 自治体の事業資料</small><b>文京区・氷見市の6事業</b><small>制度名による照合</small></div></div><div class="note">最後の接続は制度名の一致を確認したものです。国側CSVの自治体別支払額から、掲載6事業へ同額が流れたことを実証した接続ではありません。6事業を国の執行額に加算しません。</div><p>${link(n.downloadPage,'RS公式CSVダウンロード')} · ${link(n.sources['1-2_'].url,'事業概要CSV（ZIP）')} · ${link(n.sources['2-1_'].url,'予算・執行CSV（ZIP）')}</p></section><section class="panel" style="margin-top:18px"><h3>国側資料に記載された支出先</h3><p class="small">支出ブロックBの名称と金額をそのまま表示。県名の金額を県単体又は県内市町村全体の配分と断定しません。全国の自治体別内訳がすべて個別掲載されているわけではありません。</p><div class="tablewrap"><table><thead><tr><th>RS記載の支出先名</th><th class="num">支出先の合計支出額</th><th>CSVレコード</th></tr></thead><tbody>${[...n.recipients].sort((a,b)=>b.amount-a.amount).map(r=>`<tr><td>${esc(r.name)}${r.other?'（個別名称なし）':''}</td><td class="num">${oku(r.amount)}</td><td>${r.record}</td></tr>`).join('')}<tr><td><b>ブロックB合計</b></td><td class="num"><b>${oku(b.execution)}</b></td><td>支出先合計と一致</td></tr></tbody></table></div><p class="small">${link(n.sources['5-1_'].url,'支出情報CSV（ZIP）')}。論理レコード番号はヘッダーを1とする位置です。</p><details><summary>移替額と支出額を区別する</summary><p class="small">ブロックAの総務省への移替額は${oku(n.blocks.find(b=>b.block==='A').amount)}。ブロックBの交付・執行額と金額区分が異なります。AとBを合計すると同一資金を二重計上する可能性があるため、合算しません。</p></details><button class="action" id="nationalToTrace">自治体の事業・成果へ →</button></section>`}
function sourcesView(){return `<div class="section-top"><h2>根拠と、接続できている範囲。</h2>${tag('確認日 2026.11.03')}</div><section class="panel"><h3>データの接続状況</h3>${[['全国2024年度決算','収録済 · 1,741市区町村。総務省原表から歳入・歳出・指標を取込。支出ツリーでは目的別・性質別の細目を展開可能。'],['自治体決算の詳細ツリー','文京区2024・2025年度の一般会計。年度ごとの全款合計・親子合計を照合し、原資料とともに表示。対応年度は詳細ツリーで選択。全国統計とは別分類。'],['金額の整合性','目的別歳出＝性質別歳出＝概況の歳出総額が全団体で一致。歳入内訳は1,740団体で総額と一致、伊賀市のみ1千円差を明示。'],['2020～2023年度','歳入・人口・財政指標のみ。Japan Dashboard加工CSVを使用し、原表の再照合は未実施。'],['最新の当初・補正予算','文京区2026年度当初予算のみ別枠表示。全国の最新当初・補正予算は未収録。'],['国の事業ID','重点支援地方交付金：RS予算事業ID 7629を公式CSVで確認。2025年度シートの2024年度実績を収録。'],['国 → 自治体','国側の支出ブロックBと執行額を照合。国と自治体の資料は制度名で照合。全国の自治体別交付決定額との全件突合は未実施。'],['自治体 → 事業・実績','文京区3事業・氷見市3事業。国費充当額と総事業費を分け、資料の表・行・ページを明記。'],['個別事業・契約・受取先','文京区2024年度：主要施策203見出し、優良委託4案件、指定管理者12報告の収入実績を収録。統計科目との会計コード照合・支払伝票確認は未実施。'],['事業 → 成果','自治体の効果説明と実施量を表示。独立した因果効果の検証は未実施。'],['税目・間接補助・委託先','国の特定税目、都道府県経由の補助、支出先法人からの再委託は未接続。'],['更新','2026年11月3日取得のスナップショット。対応資料は毎週火曜6:17（日本時間）に更新確認。形式変更・金額不一致では公開を停止。契約・受取先など自動取込対象外の資料は個別確認。最新の取得結果はページ下部に表示。']].map(([a,b])=>`<div class="statusline"><b>${a}</b><span>${b}</span></div>`).join('')}</section><section class="panel source-list" style="margin-top:18px"><h3>一次資料と再現性</h3>${link(officialSource,'総務省：令和6年度市町村別決算状況調')}<p>都市別・町村別の概況、歳入内訳、目的別歳出内訳、性質別歳出内訳の計8表。市区町村コードで結合。親項目と内訳の重複加算を避け、原表の総額を別に保持。原単位：千円。百分率は原表の小数精度を保持しています。</p>${link('validation.json','全団体の照合結果（JSON）')}${link(source,'2020～2023年度：Japan Dashboard／デジタル庁・総務省')}<p>2026年4月24日版データテーブル。歳入・人口・指標を使用。</p>${link('https://www.digital.go.jp/resources/japandashboard/local-finance-introduction','地方財政の項目定義')}${link(national.downloadPage,'RSシステム：2025年度公式CSV')}<p>1-2（事業概要）、2-1（予算・執行）、5-1（支出情報）。RS予算事業ID 7629。合計行・支出先行・契約行を別のレコードとして扱い、同じ金額を重複加算しません。</p>${link('national.json','国の事業・抽出レコード・取得ファイル情報（JSON）')}${link('https://www.city.bunkyo.lg.jp/b002/p005854.html','文京区：交付金の使途・実績・効果')}<p>令和6年度実績報告資料p.1、No.1～3。決算確定額と異なる場合があります。事業は年度をまたぎます。</p>${link('https://www.city.himi.toyama.jp/gyosei/soshiki/zaimuka/4/3/10085.html','氷見市：交付金の実施計画・効果検証')}<p>令和6年度実施結果・効果検証資料p.1、No.11・13・17から一部収録。</p>${link('https://www.city.bunkyo.lg.jp/b002/p007692.html','文京区：2026年度当初予算')}${link('https://rs-vis.team-mir.ai/','参考サービス：チームみらいの政府予算ビュー')}<p>政府予算ビューのコード・AI評価は使用せず、公的な原データから独立して実装しています。公式提携や公認を意味しません。</p><details><summary>全国決算原表のURL・ハッシュ</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:10px">${esc(JSON.stringify(db.meta.official2024.files,null,2))}</pre></details></section><div class="note blue"><b>初版からの訂正</b><br>2024年度の加工CSVと総務省原表を比較し、一部の歳出項目に名称と値の対応ずれを確認しました。本版では元表から抽出し直し、全団体の目的別・性質別歳出を概況の総額と照合しています。国庫支出金や特別区交付金の区分、財政指標の丸めも元表に合わせて更新しました。</div><section class="panel"><h3>次に接続する情報</h3><p class="small">国側の交付決定一覧と自治体の実施計画・決算・成果指標を、事業年度、金額区分、会計範囲とともに照合します。名前の一致だけで確定接続にしません。一般財源は財源プールで止め、個別事業への推定配賦は行いません。自治体の成果は施策対象・指標定義・測定期間を揃えて比較します。</p></section>`}
function setTab(t){state.tab=t;render();$('#main').scrollIntoView({behavior:'smooth',block:'start'})}
function render(){if(!db)return;document.querySelectorAll('nav button').forEach(b=>{const active=b.dataset.tab===state.tab;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')});document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==state.tab);$('#'+state.tab).innerHTML=({overview,tree:expenditureTree,parties:partiesView,national:nationalView,trace:traceView,compare:compareView,sources:sourcesView}[state.tab])();syncUrl();bind();bindParties();bindLedger()}
function bind(){const on=(s,event,fn)=>{const e=$(s);if(e)e.addEventListener(event,fn)};on('#goTrace','click',()=>setTab('trace'));on('#openTree','click',()=>setTab('tree'));on('#treeYear2024','click',()=>{state.year='2024';$('#year').value='2024';render()});on('#retryTree','click',()=>{treeError=false;render()});document.querySelectorAll('[data-tree-mode]').forEach(b=>b.addEventListener('click',()=>{state.treeMode=b.dataset.treeMode;state.treeQuery='';render()}));on('#treeUnit','change',e=>{state.treeUnit=e.target.value;render()});on('#treeZeros','change',e=>{state.treeZeros=e.target.checked;render()});on('#treeSearch','input',e=>{const pos=e.target.selectionStart;state.treeQuery=e.target.value;render();$('#treeSearch').focus();$('#treeSearch').setSelectionRange(pos,pos)});document.querySelectorAll('[data-branch]').forEach(el=>el.addEventListener('toggle',()=>{if(el.open)openBranches.add(el.dataset.branch);else openBranches.delete(el.dataset.branch)}));on('#expandTree','click',()=>{document.querySelectorAll('[data-branch]').forEach(el=>{el.open=true;openBranches.add(el.dataset.branch)})});on('#collapseTree','click',()=>{state.treeQuery='';openBranches.clear();render()});on('#goNational','click',()=>setTab('national'));on('#nationalToTrace','click',()=>{state.scope='all';state.query='';state.category='';setTab('trace')});on('#scope','change',e=>{state.scope=e.target.value;render()});on('#showAll','click',()=>{state.scope='all';state.query='';state.category='';render()});on('#projectSearch','input',e=>{const pos=e.target.selectionStart;state.query=e.target.value;render();$('#projectSearch').focus();$('#projectSearch').setSelectionRange(pos,pos)});on('#category','change',e=>{state.category=e.target.value;render()});on('#compareCity','change',e=>{state.compare=e.target.value;render()});on('#unit','change',e=>{state.unit=e.target.value;render()});on('#download','click',download);document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>showDetail(b.dataset.detail)))}
function showDetail(id){const p=traces.projects.find(p=>p.id===id);$('#detailBody').innerHTML=`<p class="eyebrow">${esc(p.city)} · ${p.year}年度交付金資料</p><h2>${esc(p.name)}</h2><div class="detail-grid"><div><small>総事業費</small><b>${fmt(p.total)}円</b></div><div><small>国の交付金充当額</small><b>${fmt(p.grant)}円</b></div><div><small>差額（本サイト計算）</small><b>${fmt(p.total-p.grant)}円</b><small>財源の内訳は本資料だけでは特定しません。</small></div><div><small>事務費（総事業費の内数）</small><b>${p.admin==null?'未収録':fmt(p.admin)+'円'}</b><small>${p.admin==null?'ゼロを意味しません。':'総事業費の'+(p.admin/p.total*100).toFixed(1)+'%（本サイト計算）'}</small></div></div><h3>何を実現しようとしたか</h3><p>${esc(p.target)}</p><h3>実施量・公表された実績</h3><p>${esc(p.actual)}</p><h3>成果として、どこまで分かるか</h3><p>${esc(p.outcome)}</p><div class="note">${esc(p.basis)}<br>事務費の多寡だけでは効率性を判断できません。</div><p class="small">根拠：${esc(p.row)} · p.${p.page} · 確認日 ${traces.checked}<br>事業期間：${esc(p.period)}</p>${link(p.source+'#page='+p.page,'原資料PDFで照合する')}<p class="small">国のRS予算事業ID 7629と制度名で照合済み。国側の支出記録と自治体側の事業金額の直接突合は未実施。</p>`;$('#detail').showModal()}
function download(){const a=city(),b=db.cities.find(c=>c.code===state.compare),rows=[['年度','自治体コード','都道府県','自治体','分類','項目','金額_千円','人口_人','出典URL']];for(const c of [a,b]){const d=data(c);for(const [kind,values]of [['歳入',d.revenue],['歳出目的別',d.spending],['歳出性質別',d.spendingNature]])if(values)for(const [k,v]of Object.entries(values))rows.push([state.year,c.code,c.pref,c.name,kind,k,v,d.population,d.official?officialSource:source])}const text='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),aEl=document.createElement('a');aEl.href=url;aEl.download=`finance-${state.year}-${a.code}-${b.code}.csv`;aEl.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
(async()=>{try{const [r,t,n]=await Promise.all([fetch('finance.json'),fetch('trace.json'),fetch('national.json')]);if(!r.ok||!t.ok||!n.ok)throw Error('資料の読み込みに失敗');db=await r.json();traces=await t.json();national=await n.json();const params=new URLSearchParams(location.hash.slice(1));if(/^20\d{2}$/.test(params.get('ledgerYear')||''))ledgerYear=params.get('ledgerYear');if(db.cities.some(c=>c.code===params.get('city')))state.city=params.get('city');if(['2020','2021','2022','2023','2024'].includes(params.get('year')))state.year=params.get('year');if(['overview','tree','parties','national','trace','compare','sources'].includes(params.get('view')))state.tab=params.get('view');$('#year').value=state.year;$('#pref').innerHTML+=[...new Set(db.cities.map(c=>c.pref))].map(p=>`<option>${esc(p)}</option>`).join('');$('#loading').hidden=true;fillCities();$('#pref').addEventListener('change',fillCities);$('#search').addEventListener('input',fillCities);$('#city').addEventListener('change',e=>{state.city=e.target.value;render()});$('#year').addEventListener('change',e=>{state.year=e.target.value;render()});document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));$('.close').addEventListener('click',()=>$('#detail').close());$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}})}catch(e){$('#loading').innerHTML='<p class="error">データを読み込めませんでした。ページを再読み込みしてください。</p>'}})();
